  values
    (v_chapter, 'mcq', 'concept', 'bank', 1, 'A reaction in which oxidation and reduction occur simultaneously is called:', '["Neutralization reaction","Decomposition reaction","Redox reaction","Displacement reaction"]'::jsonb, 'C', 1, '89f7df12cf96', null),
