    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A ship made of iron is protected by attaching blocks of magnesium. Magnesium protects iron because it:', '["Is less reactive than iron","Reacts first with oxygen","Prevents water evaporation","Forms alloy with iron"]'::jsonb, 'B', 1, '91c186f7cf35', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A student observes that copper metal does not react with zinc sulphate solution. This indicates that copper is:', '["More reactive than zinc","Less reactive than zinc","Equal in reactivity to zinc","An oxidizing agent"]'::jsonb, 'B', 1, 'abfa146d463d', null),
