    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A reaction vessel contains hydrogen gas reacting with copper oxide. If copper oxide changes into copper, copper oxide has:', '["Been oxidized","Lost oxygen","Gained electrons from copper","Increased oxidation number"]'::jsonb, 'B', 1, '070906fce5f6', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A student accidentally scratches the zinc coating on galvanized iron. The iron still remains protected because zinc:', '["Is decorative","Acts as sacrificial metal","Is non-reactive","Absorbs moisture"]'::jsonb, 'B', 1, '4001f610c9f5', null),
