    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'An electroplated object receives metal coating because metal ions:', '["Move toward cathode and gain electrons","Move toward anode and lose electrons","React with oxygen","Evaporate during process"]'::jsonb, 'A', 1, 'a0e514da6caa', null),
